insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g8_ela_v1'
from (values
('110.24.b.2.A',2,'Which resource shows a word''s origin, or etymology?','["an etymological dictionary", "a cookbook", "a road atlas", "a thesaurus of slang"]'::jsonb,0,'Etymology traces word history.','original'),
('110.24.b.2.A',3,'A dictionary entry lists ''con-tract'' with a dot between the syllables. What does the dot show?','["the word''s rhyme", "where the word divides into syllables", "the word''s synonym", "the word''s origin"]'::jsonb,1,'Dots mark syllable breaks.','original'),
('110.24.b.2.A',4,'Why might a reader check a digital dictionary''s audio feature?','["to count words", "to find the author", "to hear the correct pronunciation", "to see the publisher"]'::jsonb,2,'Audio models pronunciation.','original'),
('110.24.b.2.B',3,'''The ambiguous directions confused us; they could be read two different ways.'' What does ''ambiguous'' mean?','["written in code", "very short", "extremely clear", "open to more than one meaning"]'::jsonb,3,'The clause after the semicolon defines it.','original'),
('110.24.b.2.B',3,'''Unlike her gregarious sister, Mia preferred quiet evenings alone.'' What does ''gregarious'' mean?','["sociable", "wealthy", "angry", "shy"]'::jsonb,0,'''Unlike'' signals an opposite.','original'),
('110.24.b.2.B',4,'''The mayor''s rhetoric, full of grand promises and stirring phrases, inspired the crowd.'' What is ''rhetoric'' here?','["a financial report", "persuasive speech", "a building plan", "a medical test"]'::jsonb,1,'Promises and stirring phrases clarify the meaning.','original'),
('110.24.b.2.C',3,'The Latin root ''bene'' means ''good.'' What does ''benefactor'' most likely mean?','["someone who travels", "someone who hides", "someone who does good for others", "someone who breaks things"]'::jsonb,2,'Bene = good.','original'),
('110.24.b.2.C',3,'The Greek root ''auto'' means ''self.'' Which word means ''a person''s own life story, written by that person''?','["geography", "photograph", "telegraph", "autobiography"]'::jsonb,3,'Auto + bio + graphy.','original'),
('110.24.b.2.C',4,'The Latin root ''dict'' means ''say.'' What does ''dictate'' mean?','["to say aloud for someone to write down", "to build", "to sail", "to erase"]'::jsonb,0,'Dict = say.','original'),
('110.24.b.5.B',3,'A reader asks, ''Why did the author include this statistic?'' This question helps the reader...','["find the index", "examine the author''s reasoning", "choose a font", "count pages"]'::jsonb,1,'Questions deepen analysis.','original'),
('110.24.b.5.B',3,'Which is a strong question to ask before reading an article titled ''The Future of Water''?','["What is the paper''s color?", "Where was it printed?", "What problems might the article say are coming?", "How tall is the author?"]'::jsonb,2,'Pre-reading questions focus on content.','original'),
('110.24.b.5.B',4,'During reading, a student asks ''How does this paragraph connect to the thesis?'' This question supports...','["ignoring structure", "skipping paragraphs", "memorizing page numbers", "monitoring how ideas fit together"]'::jsonb,3,'It checks coherence.','original'),
('110.24.b.5.C',3,'A text opens with ''Once upon a time, in a kingdom of glass...'' What genre prediction is most reasonable?','["a fairy tale or fantasy", "a newspaper obituary", "a lab report", "a bus schedule"]'::jsonb,0,'The opening signals genre.','original'),
('110.24.b.5.C',3,'A reader sees headings like ''Problem'' and ''Solution.'' Which prediction fits the text structure?','["the text is a play", "the text will describe an issue and ways to address it", "the text is a recipe", "the text is a poem"]'::jsonb,1,'Headings reveal structure.','original'),
('110.24.b.5.C',4,'A reader predicted a happy ending, but the narrator warns of ''a price paid later.'' What is the best next step?','["stop reading", "skip the warning", "revise the prediction", "keep it unchanged"]'::jsonb,2,'Readers correct predictions with new evidence.','original'),
('110.24.b.5.D',3,'Which detail most helps a reader picture a stormy sea?','["the sea was there", "it was water", "a boat existed", "waves crashed over the deck as the mast groaned"]'::jsonb,3,'Vivid sensory detail.','original'),
('110.24.b.5.D',3,'Why do readers create mental images while reading?','["to deepen understanding of the text", "to shorten the story", "to skip words", "to avoid inference"]'::jsonb,0,'Visualizing aids comprehension.','original'),
('110.24.b.5.D',4,'A reader sketches the layout of a battlefield from an author''s description. What does this show?','["a random drawing", "careful use of text details to visualize", "ignoring the text", "a summary of the title"]'::jsonb,1,'Details guide imagery.','original'),
('110.24.b.5.E',3,'A student thinks of her own move to a new school while reading about a character''s move. This is a connection to...','["the glossary", "the index", "personal experience", "another text"]'::jsonb,2,'Text-to-self.','original'),
('110.24.b.5.E',3,'An article on child labor reminds a reader of a novel set in a factory. This is a connection to...','["the page numbers", "a recipe", "the weather", "another text"]'::jsonb,3,'Text-to-text.','original'),
('110.24.b.5.E',4,'A poem about protests reminds a reader of recent civic debates. This is a connection to...','["society", "the typeface", "only the reader''s lunch", "the cover"]'::jsonb,0,'Text-to-world.','original'),
('110.24.b.5.F',3,'''Dana set the trophy on the shelf, then turned it to face the wall.'' What can be inferred?','["Dana is dusting", "Dana feels conflicted about the trophy", "Dana won easily", "Dana is in a hurry to leave"]'::jsonb,1,'Turning it away suggests mixed feelings.','original'),
('110.24.b.5.F',3,'''The coach looked at the scoreboard, sighed, and slowly took off his cap.'' What can be inferred?','["the team is far ahead", "it is raining", "the team is losing or has lost", "the game has not started"]'::jsonb,2,'Body language implies disappointment.','original'),
('110.24.b.5.F',4,'''Though the house was spotless, the table was set for two and no one ever sat down.'' What inference is best supported?','["guests are late", "the owner dislikes cleaning", "the house is brand new", "someone who used to live there is missed"]'::jsonb,3,'Details imply loss.','original'),
('110.24.b.5.G',3,'To find the key idea of a passage, a reader should...','["evaluate which details matter most", "read only the title", "count the commas", "ignore the evidence"]'::jsonb,0,'Key ideas come from weighing details.','original'),
('110.24.b.5.G',3,'A passage gives three reasons that recycling saves energy. The key idea is that...','["paper is white", "recycling helps conserve energy", "recycling is expensive", "trucks are loud"]'::jsonb,1,'Details support the key idea.','original'),
('110.24.b.5.G',4,'Which detail is least relevant to the key idea of an article on the benefits of bike lanes?','["bike lanes improve safety", "bike lanes reduce traffic", "the mayor''s favorite color", "bike lanes improve health"]'::jsonb,2,'It does not support the key idea.','original'),
('110.24.b.5.H',3,'A student reads an article and watches a video on the same topic, then forms a new conclusion from both. This is...','["copying", "guessing", "summarizing only one", "synthesis"]'::jsonb,3,'Combining sources creates new understanding.','original'),
('110.24.b.5.H',4,'Source A says online classes save money. Source B says they can reduce student engagement. Which synthesis is strongest?','["online classes offer savings but may require ways to keep students engaged", "online classes are perfect", "online classes are worthless", "the sources are the same"]'::jsonb,0,'A balanced new idea.','original'),
('110.24.b.5.H',3,'Synthesizing information means...','["ignoring conflicts", "combining ideas to form new understanding", "listing sources only", "copying each source"]'::jsonb,1,'New insight from multiple sources.','original'),
('110.24.b.5.I',3,'A reader realizes she lost the thread of a dense paragraph. What adjustment helps most?','["skip it", "read faster", "re-read it more slowly", "start another book"]'::jsonb,2,'Re-reading repairs comprehension.','original'),
('110.24.b.5.I',3,'Which is a way to monitor comprehension?','["ignoring new words", "reading the last line only", "flipping pages quickly", "pausing to restate what was just read"]'::jsonb,3,'Restating checks understanding.','original'),
('110.24.b.5.I',4,'A reader meets unfamiliar scientific terms. Which adjustment is best?','["use context, a glossary or a reference source", "stop reading", "guess without checking", "skip the page"]'::jsonb,0,'Resources clarify meaning.','original'),
('110.24.b.6.C',3,'A student claims the narrator is lonely. Which is the strongest text evidence?','["The dinner was warm.", "He ate every dinner by himself and spoke to no one for weeks.", "The narrator wore a coat.", "He lived in a house."]'::jsonb,1,'It shows isolation.','original'),
('110.24.b.6.C',4,'Why is a long quotation weaker than a short, targeted one?','["long quotes are illegal", "short quotes are always wrong", "a focused quote ties directly to the claim", "quotes need no connection"]'::jsonb,2,'Evidence should be precise.','original'),
('110.24.b.6.C',3,'Which sentence correctly introduces text evidence?','["Shaking.", "Hands are body parts.", "He is shaking, I guess.", "The author shows his fear when he writes, ''My hands would not stop shaking.''"]'::jsonb,3,'It frames the quote and links it to the claim.','original'),
('110.24.b.6.D',3,'A good summary of a long article should...','["include main ideas in logical order without opinions", "copy every sentence", "skip the main idea", "add personal opinions"]'::jsonb,0,'Summaries are concise and neutral.','original'),
('110.24.b.6.D',4,'Which sentence best paraphrases ''The legislation was met with considerable resistance from local business owners''?','["The law passed without comment.", "Many local business owners strongly opposed the law.", "Resistance is a type of business.", "Business owners wrote the law."]'::jsonb,1,'Maintains meaning in new words.','original'),
('110.24.b.6.D',3,'A paraphrase differs from a summary because a paraphrase...','["shortens a whole book to one word", "adds new facts", "restates the full idea in different words", "changes the meaning"]'::jsonb,2,'Paraphrase keeps detail; summary condenses.','original'),
('110.24.b.6.G',3,'''The porch light stayed on all night, though no one had lived there for years.'' What is an implicit meaning?','["electricity is free", "the house is new", "the porch is wide", "someone still hopes the house''s owner will return"]'::jsonb,3,'Implied emotion.','original'),
('110.24.b.6.G',3,'Which statement is an explicit meaning?','["The text says the bridge opened in 1932.", "The bridge symbolizes unity.", "The bridge seems important.", "The reader guesses the bridge is old."]'::jsonb,0,'Explicit means directly stated.','original'),
('110.24.b.6.G',4,'''She smiled for the camera, but her knuckles were white on the chair arms.'' What is the implicit meaning?','["she is thrilled", "she is more nervous than she appears", "she is cold", "she is bored"]'::jsonb,1,'Body detail contradicts the smile.','original'),
('110.24.b.6.J',3,'To challenge an author''s claim, a reader should...','["change the title", "ignore the claim", "cite relevant text evidence that conflicts with it", "shout at the page"]'::jsonb,2,'Challenges rely on evidence.','original'),
('110.24.b.6.J',4,'An author claims ''all teens prefer video games.'' Which response best challenges the claim?','["Games are bad.", "I disagree.", "The claim is red.", "The author offers no survey data, and many teens prefer sports or reading."]'::jsonb,3,'Points to unsupported generalization.','original'),
('110.24.b.6.J',3,'To defend an author''s claim, a reader could...','["point to the study the author cites as support", "say it feels right", "skip the study", "change the claim"]'::jsonb,0,'Support uses the text''s evidence.','original'),
('110.24.b.7.A',3,'In a novel, a character repeatedly chooses honesty despite costs, and eventually earns trust. What theme develops?','["costs do not matter", "integrity brings lasting respect", "trust is worthless", "lying is rewarded"]'::jsonb,1,'Events and choices reveal theme.','original'),
('110.24.b.7.A',4,'How do characters and events work together to develop a theme?','["page count decides", "the setting alone decides", "characters'' choices and their consequences reveal a message", "the title alone decides"]'::jsonb,2,'Interaction builds theme.','original'),
('110.24.b.7.A',3,'Which is a theme?','["Fear", "Helping", "A story about a scared boy", "People can overcome fear by helping others."]'::jsonb,3,'A theme is a full statement.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g8_ela_v1'
from (values
('110.24.b.7.B',3,'A character''s jealousy leads her to sabotage a friend''s project, which ruins their friendship. This shows that...','["motivations can drive events and outcomes", "setting controls plot", "titles control plot", "conflict is unrelated to motivation"]'::jsonb,0,'Behavior shapes resolution.','original'),
('110.24.b.7.B',4,'How does a character''s determination most likely affect the resolution of a conflict?','["it removes the conflict", "it pushes the character to keep trying until the problem is solved", "it changes the genre", "it ends the story at once"]'::jsonb,1,'Motivation influences resolution.','original'),
('110.24.b.7.B',3,'A hero acts out of fear of failure and avoids challenges. How does this influence the plot?','["it solves the conflict", "it adds rhymes", "it delays or complicates the resolution", "it changes the narrator"]'::jsonb,2,'Behavior affects events.','original'),
('110.24.b.7.C',3,'A narrator describes a childhood summer in the middle of a present-day scene. This is a...','["stanza", "simile", "foreshadowing", "flashback"]'::jsonb,3,'A scene from the past.','original'),
('110.24.b.7.C',4,'A novel alternates between two characters whose stories later intersect. This is a...','["parallel plot", "flashback only", "rhyme scheme", "glossary"]'::jsonb,0,'Parallel plots run side by side.','original'),
('110.24.b.7.C',3,'A side story involving a minor character that adds depth to the main plot is a...','["caption", "subplot", "thesis", "stanza"]'::jsonb,1,'Subplots enrich the main plot.','original'),
('110.24.b.7.D',3,'A character raised in a strict mountain village distrusts outsiders. How does setting shape her beliefs?','["she was born trusting everyone", "setting has no effect", "her environment taught her to value caution", "outsiders created the village"]'::jsonb,2,'Setting influences values.','original'),
('110.24.b.7.D',4,'A story set in a wartime city shows characters valuing shared food and shelter. What does this reveal?','["cities have no culture", "war has no effect", "food is unimportant", "hardship in the setting shapes what characters value"]'::jsonb,3,'Setting influences beliefs.','original'),
('110.24.b.7.D',3,'A novel set in a futuristic society where speech is controlled most likely shapes characters'' beliefs about...','["freedom and obedience", "shoe sizes", "recipes", "weather vanes"]'::jsonb,0,'A controlled setting affects values.','original'),
('110.24.b.8.A',3,'A tale of a young pilot facing a perilous journey across an unexplored sea is most likely...','["a user manual", "an adventure story", "a biography", "an encyclopedia entry"]'::jsonb,1,'Journey and danger define adventure.','original'),
('110.24.b.8.A',3,'A story set during the Civil Rights Movement, with invented characters, is...','["a myth", "realistic satire", "historical fiction", "science fiction"]'::jsonb,2,'Real period, fictional characters.','original'),
('110.24.b.8.A',4,'Which genre combines imagined technologies with scientific ideas about the future?','["mystery", "historical fiction", "memoir", "science fiction"]'::jsonb,3,'Speculative science defines the genre.','original'),
('110.24.b.8.B',3,'A poet breaks a line mid-thought so a word stands alone. What effect could this create?','["emphasis on that word", "a rhyme scheme", "a footnote", "a plot twist"]'::jsonb,0,'Line breaks stress meaning.','original'),
('110.24.b.8.B',4,'A poem uses no punctuation at all and long running lines. What effect could this create?','["a formal tone", "a flowing, breathless rhythm", "a table of data", "a list"]'::jsonb,1,'Absence of punctuation speeds pace.','original'),
('110.24.b.8.B',3,'Short lines and abrupt periods in a poem most likely create...','["a long narrative", "a smooth lullaby", "a halting or tense rhythm", "a hopeful chorus"]'::jsonb,2,'Punctuation affects pace.','original'),
('110.24.b.8.C',3,'In a play, what is a scene?','["the whole play", "the program cover", "a list of actors", "a section of an act set in one time and place"]'::jsonb,3,'Scenes divide acts.','original'),
('110.24.b.8.C',4,'How do acts and scenes help develop dramatic action?','["they organize rising action, climax and resolution", "they delete characters", "they replace dialogue", "they remove conflict"]'::jsonb,0,'Structure shapes action.','original'),
('110.24.b.8.C',3,'Which element signals a change in setting within a play?','["a new adjective", "a new scene", "a new font", "a new title"]'::jsonb,1,'Scenes mark changes.','original'),
('110.24.b.8.F',3,'An interactive web page lets readers click a map for videos and quotes. This is a...','["one-act play", "diary entry", "multimodal digital text", "limerick"]'::jsonb,2,'It mixes modes.','original'),
('110.24.b.8.F',4,'Which characteristic distinguishes digital texts from print texts?','["bindings", "page numbers", "paper covers", "hyperlinks and embedded media"]'::jsonb,3,'Digital texts link and embed media.','original'),
('110.24.b.8.F',3,'A reader evaluates a webpage by checking its author, date and links. This helps decide...','["whether the source is reliable", "the page color", "the number of ads only", "the font size"]'::jsonb,0,'Features signal reliability.','original'),
('110.24.b.8.D.i',3,'The thesis of an argumentative essay is best described as...','["a list of sources", "the controlling idea the essay supports", "a quotation", "the final citation"]'::jsonb,1,'Thesis controls the essay.','original'),
('110.24.b.8.D.i',3,'Which evidence best supports the thesis ''Public libraries benefit communities''?','["Libraries have shelves.", "Books can be heavy.", "Libraries offer free classes, internet access and books.", "Some libraries are old."]'::jsonb,2,'Specific benefits support the thesis.','original'),
('110.24.b.8.D.i',4,'A body paragraph strays from the thesis. What should the writer do?','["delete the thesis", "ignore the problem", "add more unrelated detail", "revise or cut it to stay focused on the controlling idea"]'::jsonb,3,'Focus keeps coherence.','original'),
('110.24.b.8.D.ii',3,'What is a footnote used for?','["to add a note or source at the bottom of a page", "to end a sentence", "to title the essay", "to make a list"]'::jsonb,0,'Footnotes appear at page bottom.','original'),
('110.24.b.8.D.ii',3,'Endnotes appear...','["inside every sentence", "at the end of a chapter or document", "on the cover", "before the title"]'::jsonb,1,'Endnotes are collected at the end.','original'),
('110.24.b.8.D.ii',4,'Why do authors include citations?','["to lengthen the text", "to add rhymes", "to credit sources and allow readers to verify claims", "to hide evidence"]'::jsonb,2,'Citations show credibility.','original'),
('110.24.b.8.D.iii',3,'An essay uses cause and effect in one section and compare and contrast in another. This shows...','["poor organization only", "no pattern at all", "a single pattern", "multiple organizational patterns"]'::jsonb,3,'Different patterns develop the thesis.','original'),
('110.24.b.8.D.iii',4,'Why might an author use chronological order in one section and problem-solution in another?','["each pattern helps develop a different part of the thesis", "to shorten the text", "to avoid evidence", "to confuse readers"]'::jsonb,0,'Patterns serve the argument.','original'),
('110.24.b.8.D.iii',3,'Words like ''first,'' ''next'' and ''finally'' signal which organizational pattern?','["problem and solution", "sequence", "compare and contrast", "cause and effect"]'::jsonb,1,'They mark order.','original'),
('110.24.b.8.E.i',3,'Which statement is an arguable claim?','["Schools have buses.", "Mornings come before noon.", "Schools should start later in the morning.", "Some schools have gyms."]'::jsonb,2,'A claim takes a debatable position.','original'),
('110.24.b.8.E.i',4,'To analyze an argument, a reader should...','["read only the conclusion", "count the paragraphs", "ignore the reasoning", "check whether the evidence actually supports the claim"]'::jsonb,3,'Analysis tests support.','original'),
('110.24.b.8.E.i',3,'In an argument, reasons and evidence are used to...','["support the claim", "delete the opposition", "replace the claim", "end the debate"]'::jsonb,0,'Support strengthens the claim.','original'),
('110.24.b.8.E.ii',3,'A counterargument is...','["a citation style", "an opposing view to the author''s claim", "a type of poem", "the author''s thesis"]'::jsonb,1,'It challenges the claim.','original'),
('110.24.b.8.E.ii',4,'Why do strong writers address counterarguments?','["to avoid evidence", "to shorten the essay", "to show the claim holds up against opposing views", "to weaken their claim"]'::jsonb,2,'It builds credibility.','original'),
('110.24.b.8.E.ii',3,'''Some argue homework helps learning; however, studies show limited benefits.'' What does the writer do?','["ends the essay", "defines a word", "tells a joke", "acknowledges and responds to an opposing view"]'::jsonb,3,'A counterargument and rebuttal.','original'),
('110.24.b.8.E.iii',3,'An article explaining how to choose a first guitar, with beginner terms and photos, targets...','["new musicians", "professional luthiers", "stock traders", "judges"]'::jsonb,0,'Beginner tone targets novices.','original'),
('110.24.b.8.E.iii',3,'A letter that begins ''Dear residents of Maple Street'' is written for...','["all adults worldwide", "people who live on that street", "tourists", "only students"]'::jsonb,1,'The greeting names the audience.','original'),
('110.24.b.8.E.iii',4,'How does knowing the audience help an author?','["to skip a thesis", "to lengthen the text", "to choose vocabulary, tone and evidence that will persuade them", "to avoid evidence"]'::jsonb,2,'Audience shapes choices.','original'),
('110.24.b.9.A',3,'A pamphlet urging people to conserve water has the purpose of...','["describing a mountain", "telling a joke", "teaching a dance", "persuading readers to act"]'::jsonb,3,'It aims to persuade.','original'),
('110.24.b.9.A',4,'A narrative about a family weathering a flood ends with neighbors rebuilding together. What message is conveyed?','["communities can recover through cooperation", "floods are fun", "water is useless", "families should move"]'::jsonb,0,'The ending highlights the message.','original'),
('110.24.b.9.A',3,'A science article explaining how vaccines work has the purpose of...','["selling a product", "informing", "frightening readers", "entertaining with jokes"]'::jsonb,1,'It explains facts.','original'),
('110.24.b.9.B',3,'An author uses chronological order to describe an inventor''s career. How does this support the purpose?','["it reverses causes", "it hides events", "it lets readers follow events in order", "it removes dates"]'::jsonb,2,'Structure clarifies narration.','original'),
('110.24.b.9.B',4,'A writer uses a compare-and-contrast structure to discuss two energy sources. This helps readers...','["skip details", "avoid evidence", "read backward", "see similarities and differences clearly"]'::jsonb,3,'Structure matches purpose.','original'),
('110.24.b.9.B',3,'Cause-and-effect structure in a history text helps the author...','["explain why events happened", "list unrelated facts", "add rhymes", "hide results"]'::jsonb,0,'Structure supports explanation.','original'),
('110.24.b.9.C',3,'A bold heading in an article helps readers...','["forget the topic", "locate main sections quickly", "change the genre", "skip all text"]'::jsonb,1,'Headings organize.','original'),
('110.24.b.9.C',3,'A caption under a photograph is used to...','["list the sources", "end the article", "explain what the image shows", "give the author''s address"]'::jsonb,2,'Captions explain images.','original'),
('110.24.b.9.C',4,'A magazine uses a large infographic about rising sea levels. What purpose does this serve?','["to replace the text with a poem", "to hide the evidence", "to confuse the reader", "to present data visually for quick understanding"]'::jsonb,3,'Graphics condense data.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
